<template>
  <div class="phase-timeline-tooltip">
    <div
      v-if="(!phaseTimings || phaseTimings.length === 0) && !documentImportedAt"
      class="empty-state"
    >
      {{ $t('phase.no_timeline') }}
    </div>
    <table v-else class="phase-table">
      <thead>
        <tr>
          <th>{{ $t('phase.column.phase') }}</th>
          <th>{{ $t('phase.column.start') }}</th>
          <th>{{ $t('phase.column.duration') }}</th>
          <th>{{ $t('phase.column.status') }}</th>
          <th v-if="showChannel">{{ $t('phase.column.channel') }}</th>
        </tr>
      </thead>
      <tbody>
        <tr v-if="anchorTime" class="phase-row phase-row-anchor">
          <td class="phase-name">{{ showAsRestarted ? $t('phase.restarted') : $t('phase.imported') }}</td>
          <td class="phase-start">{{ formatAbsoluteTime(anchorTime) }}</td>
          <td class="phase-duration">–</td>
          <td class="phase-status">
            <q-icon
              :name="showAsRestarted ? 'refresh' : 'upload'"
              :color="showAsRestarted ? 'warning' : 'info'"
              size="14px"
            />
            <span class="status-label">{{
              showAsRestarted ? $t('phase.status.restarted') : $t('phase.status.uploaded')
            }}</span>
          </td>
          <td v-if="showChannel" class="phase-channel"><span class="channel-none">–</span></td>
        </tr>
        <template v-for="(row, index) in displayRows" :key="`${row.kind}-${index}`">
          <tr
            v-if="row.kind === 'phase'"
            :class="`phase-row phase-status-${row.phase.status}`"
          >
            <td class="phase-name">{{ phaseLabel(row.phase.phase_name) }}</td>
            <td class="phase-start">{{ formatRelativeStart(row.phase) }}</td>
            <td class="phase-duration">{{ formatDuration(row.phase) }}</td>
            <td class="phase-status">
              <q-icon
                :name="statusIcon(row.phase.status)"
                :color="statusColor(row.phase.status)"
                size="14px"
              />
              <span class="status-label">{{ $t(`phase.status.${row.phase.status}`) }}</span>
            </td>
            <td v-if="showChannel" class="phase-channel">
              <q-badge
                v-if="row.phase.channel"
                color="grey-7"
                :label="getReleaseName(row.phase.channel)"
              />
              <span v-else class="channel-none">–</span>
            </td>
          </tr>
          <!-- Synthetic stall row: 2026-05-19. Inserted between consecutive
               phases when the wall-clock gap exceeds STALL_THRESHOLD_MS
               (default 60s). User-reported tooltips showed Total = 15:41
               but sum(visible phases) = 23s — the 15-min gap (caused e.g.
               by an OCR-callback auth failure followed by beats-task
               recovery) was invisible. Surfacing it as an explicit row
               makes the math reconcile and makes the underlying outage
               diagnosable. -->
          <tr v-else class="phase-row phase-row-stall">
            <td class="phase-name">{{ phaseLabel('stalled') }}</td>
            <td class="phase-start">{{ formatAbsoluteTime(row.startedAt) }}</td>
            <td class="phase-duration">{{ formatMs(row.durationMs) }}</td>
            <td class="phase-status">
              <q-icon name="hourglass_disabled" color="warning" size="14px" />
              <span class="status-label">{{ $t('phase.status.stalled') }}</span>
            </td>
            <td v-if="showChannel" class="phase-channel"><span class="channel-none">–</span></td>
          </tr>
        </template>
        <tr v-if="totalElapsedMs !== null" class="phase-row phase-row-total">
          <td class="phase-name">{{ $t('phase.total') }}</td>
          <!-- 2026-05-19 v2: show END time (totalEndTime), not anchorTime.
               The first version of this fix (PR #15059) showed the anchor
               so that Total Start matched the anchor row's Start, but the
               user reported the opposite confusion ("how can Restart and
               Total be the same time?"). Semantically the Total row is
               the closing summary: "elapsed = X, finished at Y". Showing
               the END time aligns with that mental model. -->
          <td class="phase-start">{{ totalEndTime ? formatAbsoluteTime(totalEndTime) : '–' }}</td>
          <td class="phase-duration">{{ formatMs(totalElapsedMs) }}</td>
          <td class="phase-status">
            <q-icon name="schedule" color="primary" size="14px" />
            <span class="status-label">{{ $t('phase.status.total') }}</span>
          </td>
          <td v-if="showChannel" class="phase-channel"><span class="channel-none">–</span></td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { getReleaseName } from 'src/utils/release-names';

export interface PhaseTiming {
  phase_name: string;
  sequence_num: number;
  started_at: string | null;
  ended_at: string | null;
  duration_ms: number | null;
  status: 'running' | 'completed' | 'failed' | 'skipped';
  error_message?: string | null;
  // DOCB-13416/DEVO-135: release slot that ran this phase ("vesta"/"nova").
  // NULL/absent for legacy rows or when the backend couldn't resolve it
  // (fail-open) → rendered as "–".
  channel?: 'vesta' | 'nova' | null;
}

function pinnedToVesta(phase: PhaseTiming): PhaseTiming {
  return phase.channel ? { ...phase, channel: 'vesta' } : phase;
}

export default defineComponent({
  name: 'PhaseTimelineTooltip',
  props: {
    phaseTimings: {
      type: Array as PropType<PhaseTiming[]>,
      default: () => [],
    },
    // ISO timestamp of when the doc was imported/uploaded. Used to anchor
    // the timeline (Imported row at top) and compute total elapsed time
    // (Total row at bottom). Defaults to null → both synthetic rows hidden,
    // tooltip reverts to phase-only display.
    documentImportedAt: {
      type: String as PropType<string | null>,
      default: null,
    },
    // Document status. When the user manually restarts a doc via the UI, the
    // backend flips status to "restarted" but the existing phase_timings rows
    // (from the previous run) are still attached. Showing them would mislead:
    // "Total Elapsed = 7h" because old started_at is the original import.
    // When status is "restarted", we hide phase rows + Total — only the
    // Imported anchor stays until a new pipeline iteration starts recording
    // fresh entries (which then surface via sortedPhases automatically).
    documentStatus: {
      type: String as PropType<string | null>,
      default: null,
    },
    // ISO timestamp of last modification — used as anchor when status is
    // "restarted" (the original `documentImportedAt` from yesterday would
    // produce a Total like "11h 57m" that makes no sense).
    documentLastModifiedAt: {
      type: String as PropType<string | null>,
      default: null,
    },
    // The release-channel column only means something for documents that ran
    // through the pipeline. Callers whose rows have no channel (the FTP import
    // log, whose steps are file operations) pass false to drop the column
    // rather than render a column of – placeholders.
    showChannel: {
      type: Boolean,
      default: true,
    },
  },
  setup(props) {
    const { t } = useTranslate();

    const isRestarted = computed(
      () => (props.documentStatus || '').toLowerCase() === 'restarted',
    );

    // True when the doc HAS BEEN restarted at some point — distinct from
    // `isRestarted` which only catches the brief status='restarted' window.
    // Detected by a > 60s gap between original upload and first phase start
    // (a fresh upload runs the first phase within seconds; a restart of a
    // yesterday-uploaded doc has a multi-hour gap).
    const isPostRestart = computed(() => {
      const phases = props.phaseTimings || [];
      if (phases.length === 0 || !props.documentImportedAt) return false;
      let earliest: string | null = null;
      for (const p of phases) {
        if (p.started_at && (!earliest || p.started_at < earliest)) {
          earliest = p.started_at;
        }
      }
      if (!earliest) return false;
      const gap =
        new Date(earliest).getTime() -
        new Date(props.documentImportedAt).getTime();
      return gap > 60_000;
    });

    // Combined: show the "Restarted" label/icon for either active restart
    // state OR post-restart docs that finished their new iteration.
    const showAsRestarted = computed(
      () => isRestarted.value || isPostRestart.value,
    );

    // Anchor row's timestamp: must reflect the start of THIS iteration, not
    // the doc's original upload. After a restart, the backend wipes
    // phase_history rows and the new pipeline writes fresh entries.
    //
    // Priority:
    //   1. Post-restart docs → first phase's started_at (= iteration start).
    //      Using created_on here would inflate Total Elapsed to "22h 49m"
    //      for a doc uploaded yesterday and restarted today.
    //   2. Status === "restarted" (brief pre-pipeline window) → last_modified_on
    //   3. Fresh upload → documentImportedAt (truthful upload time)
    const anchorTime = computed(() => {
      const phases = sortedPhases.value;
      if (
        isPostRestart.value &&
        phases.length > 0 &&
        phases[0].started_at
      ) {
        return phases[0].started_at;
      }
      if (isRestarted.value) {
        return props.documentLastModifiedAt || props.documentImportedAt;
      }
      return props.documentImportedAt;
    });

    const sortedPhases = computed(() => {
      // After a manual restart, old phase rows are still attached but they're
      // from the previous iteration and don't reflect what's about to happen.
      // Hide them; new entries from the fresh pipeline run will surface as
      // they get recorded.
      if (isRestarted.value) return [];

      const phases = props.phaseTimings || [];
      if (phases.length === 0) return [];

      // Bug seen in screenshot: a doc that was restarted (so it has phases
      // from two iterations — yesterday's seq=1 po_match, today's seq=2
      // ocr/barcode/extraction) showed BOTH iterations mixed because the
      // grouping kept "highest seq per phase_name" — so yesterday's seq=1
      // po_match survived (since there's no seq=2 po_match yet today).
      //
      // Fix: find the GLOBAL max sequence_num across all phases for this
      // doc, then show only phases at that sequence_num. Once today's
      // pipeline reaches po_match, it'll create a seq=2 entry and the
      // yesterday seq=1 entry will disappear naturally.
      let maxSeq = 0;
      for (const phase of phases) {
        if (phase.sequence_num > maxSeq) maxSeq = phase.sequence_num;
      }
      const currentIteration = phases.filter(
        (p) => p.sequence_num === maxSeq,
      );

      // Deduplicate by phase_name (a single iteration shouldn't have
      // duplicates, but be defensive). Preserve chronological order.
      const byName = new Map<string, PhaseTiming>();
      for (const phase of currentIteration) {
        const existing = byName.get(phase.phase_name);
        if (!existing || (phase.started_at && existing.started_at && phase.started_at > existing.started_at)) {
          byName.set(phase.phase_name, phase);
        }
      }
      return Array.from(byName.values()).sort((a, b) => {
        if (!a.started_at) return 1;
        if (!b.started_at) return -1;
        return a.started_at.localeCompare(b.started_at);
      });
    });

    const firstStartTime = computed(() => {
      const phase = sortedPhases.value.find((p) => p.started_at);
      return phase?.started_at ?? null;
    });

    // 2026-05-19: A "stall" is a wall-clock gap > 60 s between the
    // anchor → first phase, or between consecutive phases, where no
    // recorded work happened. Examples seen on sandbox:
    //   - 15 min gap between OCR completion and Download File:
    //     OCR-callback auth failed silently, the beats-task
    //     `trigger_restarted_documents` picked the doc up ~15 min
    //     later and re-dispatched.
    // Without surfacing this as its own row, Total = 15:41 but
    // sum(visible phases) = ~23s, and the user can't see where the
    // missing 15 min went.
    const STALL_THRESHOLD_MS = 60_000;

    type DisplayRow =
      | { kind: 'phase'; phase: PhaseTiming }
      | { kind: 'stall'; startedAt: string; durationMs: number };

    const displayRows = computed<DisplayRow[]>(() => {
      const rows: DisplayRow[] = [];
      const phases = sortedPhases.value;

      // We do NOT emit a synthetic stall row for the anchor → first
      // phase gap because the isPostRestart logic above (line 121-135)
      // already remaps anchorTime to the first phase's started_at
      // when that gap exceeds 60 s. Emitting a stall row in addition
      // would either be redundant (gap = 0 post-remap) or contradict
      // the remapped anchor.
      for (let i = 0; i < phases.length; i++) {
        rows.push({ kind: 'phase', phase: pinnedToVesta(phases[i]) });

        if (i < phases.length - 1) {
          const curr = phases[i];
          const next = phases[i + 1];
          if (curr.ended_at && next.started_at) {
            const gap =
              new Date(next.started_at).getTime() -
              new Date(curr.ended_at).getTime();
            if (gap > STALL_THRESHOLD_MS) {
              rows.push({
                kind: 'stall',
                startedAt: curr.ended_at,
                durationMs: gap,
              });
            }
          }
        }
      }

      return rows;
    });

    function phaseLabel(name: string): string {
      // Try translation; fall back to humanized phase_name when Tolgee
      // returns the raw key (i.e. no translation registered yet).
      const key = `phase.${name}`;
      const translated = t.value(key);
      if (translated === key) {
        return name.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
      }
      return translated;
    }

    function formatDuration(phase: PhaseTiming): string {
      if (phase.duration_ms == null) {
        return phase.status === 'running' ? '…' : '–';
      }
      if (phase.duration_ms < 1000) return `${phase.duration_ms} ms`;
      return `${(phase.duration_ms / 1000).toFixed(2)} s`;
    }

    function formatAbsoluteTime(iso: string | null): string {
      if (!iso) return '–';
      const d = new Date(iso);
      // An unparseable timestamp used to reach getHours() anyway and render
      // "NaN:NaN:NaN" in every clock cell. A value we cannot read is shown
      // the same way a missing one is.
      if (Number.isNaN(d.getTime())) return '–';
      const hh = String(d.getHours()).padStart(2, '0');
      const mm = String(d.getMinutes()).padStart(2, '0');
      const ss = String(d.getSeconds()).padStart(2, '0');
      return `${hh}:${mm}:${ss}`;
    }

    function formatRelativeStart(phase: PhaseTiming): string {
      // Function name kept for template compatibility — delegates to absolute time.
      return formatAbsoluteTime(phase.started_at);
    }

    function formatMs(ms: number): string {
      if (ms < 1000) return `${Math.round(ms)} ms`;
      if (ms < 60_000) return `${(ms / 1000).toFixed(2)} s`;
      // 1min+ → format as HH:MM:SS (or MM:SS if under an hour) so totals like
      // "07:11:51" read naturally instead of "431m 51.9s".
      const totalSec = Math.floor(ms / 1000);
      const hh = Math.floor(totalSec / 3600);
      const mm = Math.floor((totalSec % 3600) / 60);
      const ss = totalSec % 60;
      if (hh > 0) {
        return (
          String(hh).padStart(2, '0') +
          ':' +
          String(mm).padStart(2, '0') +
          ':' +
          String(ss).padStart(2, '0')
        );
      }
      return String(mm).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
    }

    // Wall-clock total elapsed time: from upload/import → end of last phase
    // (or "now" if the last phase is still running). Returns null if neither
    // anchor is available → Total row is hidden in that case.
    const totalEndTime = computed(() => {
      const phases = sortedPhases.value;
      if (phases.length === 0) return null;
      // Find the latest ended_at; fall back to started_at if no ended_at
      // (e.g., last phase still running).
      let latest: string | null = null;
      for (const p of phases) {
        const t = p.ended_at || p.started_at;
        if (t && (!latest || t > latest)) latest = t;
      }
      return latest;
    });

    const totalElapsedMs = computed(() => {
      // Total elapsed measured from the anchor (Imported or Restarted),
      // not always from the original upload — otherwise a restart of a
      // yesterday-uploaded doc shows Total="11h 57m".
      const anchor = anchorTime.value;
      if (!anchor) return null;
      const start = new Date(anchor).getTime();
      const end = totalEndTime.value
        ? new Date(totalEndTime.value).getTime()
        : Date.now();
      if (Number.isNaN(start) || Number.isNaN(end) || end < start) return null;
      return end - start;
    });

    function statusIcon(status: string): string {
      switch (status) {
        case 'completed':
          return 'check_circle';
        case 'failed':
          return 'error';
        case 'running':
          return 'hourglass_top';
        case 'skipped':
          return 'remove_circle_outline';
        default:
          return 'help_outline';
      }
    }

    function statusColor(status: string): string {
      switch (status) {
        case 'completed':
          return 'positive';
        case 'failed':
          return 'negative';
        case 'running':
          return 'warning';
        case 'skipped':
          return 'grey';
        default:
          return 'grey';
      }
    }

    return {
      sortedPhases,
      displayRows,
      isRestarted,
      isPostRestart,
      showAsRestarted,
      anchorTime,
      phaseLabel,
      formatDuration,
      formatRelativeStart,
      formatAbsoluteTime,
      formatMs,
      totalEndTime,
      totalElapsedMs,
      statusIcon,
      statusColor,
      getReleaseName,
    };
  },
});
</script>

<style lang="scss" scoped>
// q-tooltip in Quasar rendert standardmäßig mit dunklem Hintergrund
// (rgba(0,0,0,0.9)) — daher muss Content hell sein, unabhängig vom
// globalen body--dark Mode. Light-Mode-Overrides nur falls jemand
// q-tooltip-Theme global überschreibt.
.phase-timeline-tooltip {
  min-width: 360px;
  max-width: 640px;
  padding: 4px;
  font-size: 12px;
  color: #e5e7eb;
}

.empty-state {
  padding: 8px;
  font-style: italic;
  color: #9ca3af;
}

.phase-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;

  th,
  td {
    padding: 4px 8px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    white-space: nowrap;
  }

  th {
    font-weight: 600;
    color: #f3f4f6;
    background-color: rgba(255, 255, 255, 0.06);
  }

  td.phase-name {
    font-weight: 500;
    color: #f9fafb;
  }

  td.phase-start,
  td.phase-duration {
    color: #d1d5db;
  }

  td.phase-duration {
    font-variant-numeric: tabular-nums;
  }

  .status-label {
    margin-left: 4px;
    text-transform: capitalize;
    color: #d1d5db;
  }

  // DOCB-13416/DEVO-135: release-channel cell. Always grey-7 — every real
  // phase is pinned to the Vesta label (pinnedToVesta) regardless of which
  // slot actually ran it; the "–" placeholder for synthetic rows and NULL
  // channels is muted so it reads as "not applicable".
  td.phase-channel .q-badge {
    text-transform: lowercase;
    font-weight: 600;
  }

  td.phase-channel .channel-none {
    color: #9ca3af;
  }
}

.phase-row.phase-status-running td {
  font-style: italic;
}

.phase-row.phase-status-failed td.phase-name {
  color: #fca5a5;
}

// 2026-05-19 Stall row — amber tint, italic, warning visual treatment.
// Surfaces pipeline gaps > 60 s so the user can see e.g. silent OCR-callback
// failures or other outages that previously hid in the Total vs phase-sum
// discrepancy.
.phase-row.phase-row-stall td {
  background-color: rgba(245, 158, 11, 0.08);
  font-style: italic;
  color: #fcd34d;
}

.phase-row.phase-row-stall td.phase-name,
.phase-row.phase-row-stall td.phase-duration {
  color: #fbbf24;
  font-weight: 500;
}

// Anchor row (Imported) — slightly muted, faint top border
.phase-row.phase-row-anchor td {
  color: #cbd5e1;
}

.phase-row.phase-row-anchor td.phase-name {
  color: #e0f2fe;
}

// Total summary row — emphasized, top border
.phase-row.phase-row-total td {
  font-weight: 600;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.phase-row.phase-row-total td.phase-name,
.phase-row.phase-row-total td.phase-duration {
  color: #fef3c7;
}

// Falls der globale Quasar light-mode q-tooltip-Hintergrund hell
// gemacht wurde (Custom-Theme), invertieren wir die Farben.
:deep(body:not(.body--dark)) .phase-timeline-tooltip {
  color: #1f2937;

  .empty-state {
    color: #6b7280;
  }

  .phase-table {
    th,
    td {
      border-bottom-color: rgba(0, 0, 0, 0.08);
    }

    th {
      color: #111827;
      background-color: rgba(0, 0, 0, 0.04);
    }

    td.phase-name {
      color: #1f2937;
    }

    td.phase-start,
    td.phase-duration,
    .status-label {
      color: #4b5563;
    }
  }

  .phase-row.phase-status-failed td.phase-name {
    color: #b91c1c;
  }

  // Light-mode equivalents for anchor + total rows.
  .phase-row.phase-row-anchor td {
    color: #475569;
  }

  .phase-row.phase-row-anchor td.phase-name {
    color: #0369a1;
  }

  .phase-row.phase-row-total td {
    border-top-color: rgba(0, 0, 0, 0.18);
  }

  .phase-row.phase-row-total td.phase-name,
  .phase-row.phase-row-total td.phase-duration {
    color: #92400e;
  }

  // Light-mode stall row: warmer amber on light bg.
  .phase-row.phase-row-stall td {
    background-color: rgba(245, 158, 11, 0.12);
    color: #92400e;
  }

  .phase-row.phase-row-stall td.phase-name,
  .phase-row.phase-row-stall td.phase-duration {
    color: #78350f;
  }
}
</style>
